INSERT INTO `bc_page_texts_91` (`page_id`, `slot`, `text`) VALUES
    (2129066, 0, ''),
    (2129066, 1, ''),
    (2129066, 2, ''),
    (2129116, 0, 'Dark magic starts here.'),
    (2129116, 1, ''),
    (2129116, 2, ''),
    (2129122, 0, ''),
    (2129122, 1, ''),
    (2129122, 2, ''),
    (2129147, 0, 'However you place your essential Furniture, it''s the finishing touches that count!'),
    (2129147, 1, ''),
    (2129147, 2, ''),
    (2129150, 0, 'After a busy day making new friends and exploring the Hotel you''ll need a good night''s sleep! Pick your fave from our range of stylish beds and get some much needed rest. '),
    (2129150, 1, ''),
    (2129150, 2, ''),
    (2129151, 0, 'Rugs for all occasions, all non-slip and washable.'),
    (2129151, 1, ''),
    (2129151, 2, ''),
    (2129152, 0, 'You can''t just leave your friends standing there when you invite them over! Have a look at our huge selection of chairs and take your pick.'),
    (2129152, 1, ''),
    (2129152, 2, ''),
    (2129154, 0, ''),
    (2129154, 1, ''),
    (2129154, 2, ''),
    (2129155, 0, 'Divide and conquer! A well-placed divider can really tie your room together. Take a look below to see what''s on offer. '),
    (2129155, 1, ''),
    (2129155, 2, ''),
    (2129156, 0, ''),
    (2129156, 1, ''),
    (2129156, 2, ''),
    (2129158, 0, ''),
    (2129158, 1, ''),
    (2129158, 2, ''),
    (2129160, 0, 'Ambient lighting is essential'),
    (2129160, 1, ''),
    (2129160, 2, ''),
    (2129161, 0, 'What''s a room without a table? Serve drinks and snacks or simply sit around for some good old chit-chat. Which table suits your room best? '),
    (2129161, 1, ''),
    (2129161, 2, ''),
    (2129163, 0, 'Want some privacy? Go inside a tent to have private conversations in public places. Habbos outside will not see your chat nor will they see what''s happening on the inside.'),
    (2129163, 1, 'Click on an item for details.'),
    (2129163, 2, ''),
    (2129164, 0, ''),
    (2129164, 1, ''),
    (2129164, 2, ''),
    (2129166, 0, 'Adorn your walls with wondrous works of art, posters, plaques, and wall hangings. The Gallery is bursting with items to suit all tastes, from kitsch to cool, traditional to modern.'),
    (2129166, 1, ''),
    (2129166, 2, ''),
    (2129168, 0, 'Let some sunshine in! Our windows come in many styles to give a unique look to your room. Who said your room can''t have a view?'),
    (2129168, 1, ''),
    (2129168, 2, ''),
    (2129170, 0, 'Habbo''s 25th demands pool party perfection. Get ready to lounge, dance, and get wild!'),
    (2129170, 1, ''),
    (2129170, 2, ''),
    (2129171, 0, 'Here you can find all the tools necessary to build your very own 20th birthday ballroom. Get to it!'),
    (2129171, 1, ''),
    (2129171, 2, ''),
    (2129172, 0, ''),
    (2129172, 1, ''),
    (2129172, 2, ''),
    (2129173, 0, ''),
    (2129173, 1, ''),
    (2129173, 2, ''),
    (2129174, 0, 'Go and check out the mini furni line we released for our Ancient Greek revisitation event'),
    (2129174, 1, ''),
